const fs=require('fs'),path=require('path'),vm=require('vm'),assert=require('assert'),root=path.resolve(__dirname,'..');const ctx={window:{EUROSCOUT_CLUB_DIRECTORY:[]},structuredClone,searchFold:s=>String(s||'').toLowerCase(),canonKey:s=>s};vm.createContext(ctx);for(const file of ['membership-data.js','official-rosters-2026.js','data/fiba-club-competitions-2026.js','euroscout-fiba-club-competitions.js','euroscout-official-rosters.js'])vm.runInContext(fs.readFileSync(path.join(root,file),'utf8'),ctx);const data=ctx.window.EuroScoutFIBAClub.data;assert.equal(data.roster.filter(p=>p.competition==='bcl').length,472);assert.equal(data.historicalRoster.length,4);assert.equal(data.competitions.bcl.statsPlayers.length,346);assert(data.competitions.bcl.statsPlayers.every(p=>p.g>0));assert.equal(data.competitions.fec.checked,'2026-10-07T13:48:16.410Z');assert(data.competitions.bcl.checked.startsWith('2026-10-14'));
